"""Read-only destination status and verification."""
import os, stat, hashlib, json
import dump_cmd


def changes(source, destination, persistent_state=None):
    result=[]
    source=os.path.abspath(os.path.expanduser(source))
    state_path=persistent_state or os.path.join(os.path.expanduser('~'),'.cache','chezmoi','script-state.json')
    try:
        with open(state_path,encoding='utf-8') as f: script_state=json.load(f)
    except (OSError,ValueError): script_state={}
    for name, entry in dump_cmd.entries(source).items():
        if entry.get('type')=='script':
            condition=entry.get('condition','always')
            key=source+'\0'+name
            digest=hashlib.sha256(entry.get('contents','').encode('utf-8')).hexdigest()
            if condition not in ('once','onchange') or script_state.get(key)!=digest:
                result.append((' R',name))
            continue
        path=os.path.join(destination,*name.split('/'))
        if not os.path.lexists(path):
            result.append((' A',name)); continue
        if entry.get('type')=='symlink':
            if not os.path.islink(path) or os.readlink(path)!=entry.get('linkname',''):
                result.append((' M',name))
            continue
        if entry.get('type')=='dir':
            if not os.path.isdir(path) or os.path.islink(path):
                result.append((' M',name))
            elif stat.S_IMODE(os.stat(path).st_mode)!=entry.get('perm',0o755):
                result.append((' M',name))
            continue
        try:
            if os.path.islink(path) or not os.path.isfile(path):
                result.append((' M',name)); continue
            with open(path,'rb') as f: contents=f.read()
            if contents != entry.get('contents','').encode('utf-8') or stat.S_IMODE(os.stat(path).st_mode)!=entry.get('perm',0o644):
                result.append((' M',name))
        except (OSError,UnicodeError):
            result.append((' M',name))
    result.sort(key=lambda item: (dump_cmd.SCRIPT_PHASES.get(item[1], 2), item[1]))
    return result


def handle(command, source, destination, args=()):
    style='relative'; selectors=[]; state_path=None; i=0
    while i<len(args):
        a=args[i]
        if a=='--persistent-state' and i+1<len(args):
            state_path=os.path.expanduser(args[i+1]); i+=2; continue
        elif a.startswith('--persistent-state='):
            state_path=os.path.expanduser(a.split('=',1)[1]); i+=1; continue
        if a in ('-p','--path-style') and i+1<len(args): i+=1; style=args[i]
        elif a.startswith('--path-style='): style=a.split('=',1)[1]
        elif a.startswith('-'): pass
        else: selectors.append(a)
        i+=1
    destination=os.path.abspath(os.path.expanduser(destination))
    selected=[]
    managed_names=set(dump_cmd.entries(source))
    for item in selectors:
        p=os.path.abspath(os.path.expanduser(item))
        try: rel=os.path.relpath(p,destination)
        except ValueError: rel='..'
        if rel=='..' or rel.startswith('..'+os.sep):
            return f'chezmoi: {p}: not in destination directory ({destination})\n',1
        rel=rel.replace(os.sep,'/')
        if not any(n==rel or n.startswith(rel.rstrip('/')+'/') for n in managed_names):
            return f'chezmoi: {p}: not managed\n',1
        selected.append(rel)
    changed=changes(source,destination,state_path)
    if command in ('status','verify'):
        changed.sort(key=lambda item: (dump_cmd.SCRIPT_PHASES.get(item[1], 2), item[1]))
    if selected:
        changed=[(status,name) for status,name in changed if any(name==p or name.startswith(p.rstrip('/')+'/') for p in selected)]
    if command=='verify': return ('',1 if changed else 0)
    if style=='absolute': changed=[(s,os.path.join(destination,*n.split('/'))) for s,n in changed]
    return (''.join(f'{status} {name}\n' for status,name in changed),0)


def git_blob(data):
    import hashlib
    return hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()


def pending_script(source,name,entry):
    condition=entry.get('condition','always')
    if condition not in ('once','onchange'): return True
    state_path=os.path.join(os.path.expanduser('~'),'.cache','chezmoi','script-state.json')
    try:
        with open(state_path,encoding='utf-8') as f: state=json.load(f)
    except (OSError,ValueError): state={}
    key=os.path.abspath(os.path.expanduser(source))+'\0'+name
    digest=hashlib.sha256(entry.get('contents','').encode('utf-8')).hexdigest()
    return state.get(key)!=digest


def diff(source,destination,selectors=None):
    import difflib
    import hashlib
    out=[]
    target_entries=dump_cmd.entries(source)
    if selectors:
        target_entries={n:e for n,e in target_entries.items() if any(n==p or n.startswith(p.rstrip('/')+'/') for p in selectors)}
    for name, entry in sorted(target_entries.items(), key=lambda item: (dump_cmd.SCRIPT_PHASES.get(item[0], 2), item[0])):
        kind=entry.get('type')
        if kind=='dir':
            path=os.path.join(destination,*name.split('/'))
            if not os.path.lexists(path):
                mode=0o040000 | entry.get('perm',0o755)
                emptyhash=git_blob(b'')
                out.append(f'diff --git a/{name} b/{name}\nnew file mode {mode:o}\nindex {"0"*40}..{emptyhash}\n--- /dev/null\n+++ b/{name}\n')
            continue
        if kind=='symlink':
            path=os.path.join(destination,*name.split('/'))
            exists=os.path.lexists(path)
            new=(entry.get('linkname','')+'\n').encode('utf-8')
            try:
                if os.path.islink(path): old=(os.readlink(path)+'\n').encode('utf-8')
                elif os.path.isfile(path):
                    with open(path,'rb') as f: old=f.read()
                else: old=b''
            except OSError: old=b''
            if old==new and exists and os.path.islink(path): continue
            out.append(f'diff --git a/{name} b/{name}\n')
            if not exists: out.append('new file mode 120000\n')
            oldhash=git_blob(old) if exists else '0'*40
            out.append(f'index {oldhash}..{git_blob(new)}\n')
            out.append(f'--- a/{name}\n' if exists else '--- /dev/null\n')
            out.append(f'+++ b/{name}\n')
            oldlines=old.decode('utf-8','replace').splitlines(keepends=True)
            newlines=new.decode('utf-8','replace').splitlines(keepends=True)
            generated=list(difflib.unified_diff(oldlines,newlines,fromfile='',tofile='',lineterm='\n'))
            for line in generated[2:]:
                out.append(line if line.endswith('\n') else line+'\n\\ No newline at end of file\n')
            continue
        if kind not in ('file','script'): continue
        path=os.path.join(destination,*name.split('/'))
        new=entry.get('contents','').encode('utf-8')
        try:
            with open(path,'rb') as f: old=f.read()
        except OSError: old=b''
        exists=os.path.lexists(path)
        newperm=0o755 if kind=='script' else entry.get('perm',0o644)
        mode=0o100000 | newperm
        oldmode=stat.S_IMODE(os.stat(path).st_mode) if exists and not os.path.islink(path) else None
        if exists and old==new and oldmode==newperm: continue
        out.append(f'diff --git a/{name} b/{name}\n')
        if exists and oldmode is not None and oldmode!=newperm:
            out.append(f'old mode {0o100000|oldmode:o}\nnew mode {mode:o}\n')
        if old==new:
            continue
        oldhash=git_blob(old) if exists else '0'*40
        newhash=git_blob(new)
        if not exists: out.append(f'new file mode {mode:o}\n')
        index_mode=f' {0o100000|oldmode:o}' if exists and oldmode is not None and oldmode==newperm else ''
        out.append(f'index {oldhash}..{newhash}{index_mode}\n')
        oldlines=old.decode('utf-8','replace').splitlines(keepends=True)
        newlines=new.decode('utf-8','replace').splitlines(keepends=True)
        if exists: out.append(f'--- a/{name}\n')
        else: out.append('--- /dev/null\n')
        out.append(f'+++ b/{name}\n')
        generated=list(difflib.unified_diff(oldlines,newlines,fromfile='',tofile='',lineterm='\n'))
        # The first two headers are supplied above; retain hunk and body only.
        for line in generated[2:]:
            if line.endswith('\n'):
                out.append(line)
            else:
                out.append(line+'\n\\ No newline at end of file\n')
    return ''.join(out)
"""Filesystem application of the rendered target state."""
import os, stat, subprocess, json, hashlib, tempfile
import dump_cmd


def handle(source,destination,dry_run=False,verbose=False,args=()):
    source=os.path.abspath(os.path.expanduser(source)); destination=os.path.abspath(os.path.expanduser(destination))
    entries=dump_cmd.entries(source)
    selectors=[]; state_override=None; i=0
    while i<len(args):
        a=args[i]
        if a in ('-p','--path-style','--include','-i','--exclude','-x','--persistent-state') and i+1<len(args):
            if a=='--persistent-state': state_override=args[i+1]
            i+=1
        elif a.startswith('--persistent-state='): state_override=a.split('=',1)[1]
        elif a.startswith('-'): pass
        else:
            path=os.path.abspath(os.path.expanduser(a))
            try: rel=os.path.relpath(path,destination)
            except ValueError: rel='..'
            rel=rel.replace(os.sep,'/')
            if rel=='..' or rel.startswith('../') or not any(n==rel or n.startswith(rel.rstrip('/')+'/') for n in entries):
                return '',f'chezmoi: {path}: not managed\n',1
            selectors.append(rel)
        i+=1
    if dry_run:
        import state_read
        return (state_read.diff(source,destination,selectors or None) if verbose else ''),'',0
    state_dir=os.path.join(os.path.expanduser('~'),'.cache','chezmoi')
    state_path=state_override or os.path.join(state_dir,'script-state.json')
    state_dir=os.path.dirname(os.path.abspath(os.path.expanduser(state_path)))
    try:
        with open(state_path,encoding='utf-8') as f: script_state=json.load(f)
    except (OSError,ValueError): script_state={}
    state_changed=False
    errors=[]; output=[]
    for name,entry in sorted(entries.items(), key=lambda item: (dump_cmd.SCRIPT_PHASES.get(item[0], 2), item[0])):
        if selectors and not any(name==p or name.startswith(p.rstrip('/')+'/') for p in selectors): continue
        path=os.path.join(destination,*name.split('/'))
        try:
            os.makedirs(os.path.dirname(path),exist_ok=True)
            if entry.get('type')=='script':
                condition=entry.get('condition','always')
                state_key=source+'\0'+name
                content=entry.get('contents','')
                digest=hashlib.sha256(content.encode('utf-8')).hexdigest()
                if condition in ('once','onchange') and script_state.get(state_key)==digest:
                    continue
                fd,script_path=tempfile.mkstemp(prefix='chezmoi-',suffix='.test')
                try:
                    with os.fdopen(fd,'w',encoding='utf-8') as f: f.write(content)
                    os.chmod(script_path,0o700)
                    try:
                        proc=subprocess.run([script_path],cwd=destination,capture_output=True,text=True)
                    except OSError as e:
                        errors.append(f'chezmoi: {os.path.basename(name)}: fork/exec {script_path}: {e.strerror.lower() if e.strerror else e}')
                        continue
                    if proc.stdout: output.append(proc.stdout)
                    if proc.stderr: errors.append(proc.stderr.rstrip('\n'))
                    if proc.returncode: errors.append(f'chezmoi: script {name} failed with exit code {proc.returncode}')
                    elif condition in ('once','onchange'):
                        script_state[state_key]=digest
                        state_changed=True
                finally:
                    try: os.unlink(script_path)
                    except OSError: pass
                continue
            if entry.get('type')=='dir':
                if os.path.lexists(path) and (not os.path.isdir(path) or os.path.islink(path)):
                    if os.path.isdir(path) and not os.path.islink(path):
                        errors.append(f'chezmoi: {path}: is not a directory'); continue
                    os.unlink(path)
                os.makedirs(path,exist_ok=True)
                os.chmod(path,entry.get('perm',0o755))
            elif entry.get('type')=='symlink':
                link=entry.get('linkname','')
                if os.path.islink(path) and os.readlink(path)==link: continue
                if os.path.lexists(path):
                    if os.path.isdir(path) and not os.path.islink(path):
                        errors.append(f'chezmoi: {path}: is a directory'); continue
                    os.unlink(path)
                os.symlink(link,path)
            else:
                data=entry.get('contents','').encode('utf-8')
                if os.path.isfile(path) and not os.path.islink(path):
                    try:
                        if open(path,'rb').read()==data and stat.S_IMODE(os.stat(path).st_mode)==entry.get('perm',0o644): continue
                    except OSError: pass
                elif os.path.lexists(path):
                    errors.append(f'chezmoi: {path}: is not a regular file'); continue
                with open(path,'wb') as f: f.write(data)
                os.chmod(path,entry.get('perm',0o644))
        except OSError as e:
            errors.append(f'chezmoi: {path}: {e.strerror or e}')
    if state_changed:
        try:
            os.makedirs(state_dir,exist_ok=True)
            with open(state_path,'w',encoding='utf-8') as f: json.dump(script_state,f,sort_keys=True)
        except OSError:
            pass
    return ''.join(output), ''.join(x+'\n' for x in errors), 1 if errors else 0

