    for arg in args:
        if arg in ("--source-path", "--absolute", "--relative"):
            continue
        if arg.startswith("-"):
            continue
        paths.append(os.path.abspath(os.path.expanduser(arg)))
    root = destination if command == "source-path" else source
    if not paths:
        return (source if command == "source-path" else destination) + "\n", "", 0
    result, errors = [], []
    for path in paths:
        try:
            rel = os.path.relpath(path, root)
        except ValueError:
            rel = ".."
        if rel == ".." or rel.startswith(".." + os.sep):
            errors.append(f"chezmoi: {path}: not in {('destination directory (' + destination + ')' if command == 'source-path' else source)}")
            continue
        if command == "source-path":
            parts = rel.split(os.sep)
            current = source
            encoded = []
            for p in parts:
                enc = ("dot_" + p[1:]) if p.startswith(".") else p
                try:
                    matches = [n for n in os.listdir(current) if unencode(n) == p]
                except OSError:
                    matches = []
                if matches:
                    enc = sorted(matches)[0]
                encoded.append(enc)
                current = os.path.join(current, enc)
            sp = current
            import dump_cmd
            managed=set(dump_cmd.entries(source))
            target_rel=rel.replace(os.sep,'/')
            if target_rel not in managed:
                errors.append(f"chezmoi: {path}: not managed")
                continue
            if not os.path.lexists(sp):
                found = next((sp + ext for ext in (".tmpl", ".age", ".tmpl.age", ".literal", ".symlink") if os.path.lexists(sp + ext)), None)
                if found is None:
                    errors.append(f"chezmoi: {path}: not managed")
                    continue
                sp = found
            result.append(sp)
        else:
            if not os.path.exists(path):
                errors.append(f"chezmoi: stat {path}: no such file or directory")
                continue
            parts = [unencode(p) for p in rel.split(os.sep)]
            if parts:
                for suffix in (".tmpl", ".age", ".literal", ".symlink"):
                    if parts[-1].endswith(suffix):
                        parts[-1] = parts[-1][:-len(suffix)]
                        break
            tp = os.path.join(destination, *parts)
            result.append(tp)
    return "".join(x + "\n" for x in result), "".join(x + "\n" for x in errors), 1 if errors else 0
"}

